import * as React from "react"
import { MoreHorizontal } from "lucide-react"
import { Alert } from "@atlas/ui-web/compositions/Alert/Alert"
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription,
  AlertDialogFooter, AlertDialogTitle } from "@atlas/ui-web/compositions/AlertDialog/AlertDialog"
import { Card, CardContent, CardHeader, CardTitle } from "@atlas/ui-web/compositions/Card/Card"
import { Dialog, DialogBody, DialogClose, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@atlas/ui-web/compositions/Dialog/Dialog"
import { Field } from "@atlas/ui-web/compositions/Field/Field"
import { toast } from "@atlas/ui-web/compositions/Toast/Toast"
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from "@atlas/ui-web/patterns/DropdownMenu/DropdownMenu"
import { Avatar } from "@atlas/ui-web/primitives/Avatar/Avatar"
import { Badge } from "@atlas/ui-web/primitives/Badge/Badge"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { Input } from "@atlas/ui-web/primitives/Input/Input"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@atlas/ui-web/primitives/Select/Select"
import { Skeleton } from "@atlas/ui-web/primitives/Skeleton/Skeleton"
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@atlas/ui-web/primitives/Table/Table"

type Role = "Owner" | "Admin" | "Member"
type Person = { id: string; name: string; email: string; role: Role; status: "Active" | "Pending"; you?: boolean }

const ROLES: Role[] = ["Owner", "Admin", "Member"]
const initials = (name: string) => name.split(" ").map((p) => p[0]).join("")

const title = { fontSize: "var(--atlas-text-h1)" }
const muted = { fontSize: "var(--atlas-text-body-sm)", color: "var(--atlas-foreground-muted)" }
const hidden = { position: "absolute", inlineSize: 1, blockSize: 1, overflow: "hidden", clipPath: "inset(50%)" } as const

// Mount <Toaster /> once near the app root; toast() confirms each saved role change.
export function MembersPage({ members, loading, onInvite, onChangeRole, onRemove }: {
  members: Person[]
  loading?: boolean
  /** Rejects with a readable reason on failure. */
  onInvite: (email: string, role: Role) => Promise<void>
  onChangeRole: (id: string, role: Role) => Promise<void>
  onRemove: (id: string) => Promise<void>
}) {
  const [inviting, setInviting] = React.useState(false)
  const [email, setEmail] = React.useState("")
  const [inviteRole, setInviteRole] = React.useState<Role>("Member")
  const [sending, setSending] = React.useState(false)
  const [failure, setFailure] = React.useState<string | null>(null)
  const [removing, setRemoving] = React.useState<Person | null>(null)
  const [removeBusy, setRemoveBusy] = React.useState(false)

  const owners = members.filter((m) => m.role === "Owner" && m.status === "Active")
  const lastOwner = owners.length === 1 ? owners[0] : null

  const send = async () => {
    setSending(true)
    setFailure(null)
    try {
      await onInvite(email, inviteRole)
      setInviting(false)
      setEmail("")
    } catch (e) {
      // Keep the Dialog open and the typed values so the user can retry.
      setFailure(e instanceof Error ? e.message : "The invite could not be sent.")
    } finally {
      setSending(false)
    }
  }

  const changeRole = async (p: Person, role: Role) => {
    try {
      await onChangeRole(p.id, role)
      toast({ variant: "success", title: `${p.name} is now ${role === "Admin" ? "an" : "a"} ${role}` })
    } catch {
      toast({ variant: "danger", title: "Couldn't change the role", description: `${p.name} is still ${p.role}.` })
    }
  }

  const confirmRemove = async () => {
    if (!removing) return
    setRemoveBusy(true)
    try {
      await onRemove(removing.id)
      setRemoving(null)
    } finally {
      setRemoveBusy(false)
    }
  }

  return (
    <div style={{ display: "grid", gap: "var(--atlas-spacing-4)", maxInlineSize: "48rem" }}>
      <div style={{ display: "flex", flexWrap: "wrap", alignItems: "center", justifyContent: "space-between", gap: "var(--atlas-spacing-4)" }}>
        <h1 style={title}>Members</h1>
        <Button variant="primary" onClick={() => setInviting(true)}>Invite member</Button>
      </div>

      {lastOwner && (
        <Alert
          variant="info"
          title={`${lastOwner.name.split(" ")[0]} Lee is the only Owner`.replace(/^\S+ Lee/, lastOwner.name)}
          description={`Make another member an Owner before changing this role or removing ${lastOwner.name.split(" ")[0]}.`}
        />
      )}

      {loading ? (
        <div role="status" aria-label="Loading members" style={{ display: "grid", gap: "var(--atlas-spacing-4)" }}>
          <Skeleton /><Skeleton /><Skeleton /><Skeleton />
        </div>
      ) : (
        <Card variant="outlined">
          <CardHeader><CardTitle>Members</CardTitle></CardHeader>
          <CardContent>
            <Table aria-label="Members">
              <TableHeader>
                <TableRow>
                  <TableHead>Member</TableHead>
                  <TableHead>Role</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead><span style={hidden}>Actions</span></TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {members.map((p) => {
                  const protectedOwner = p.id === lastOwner?.id
                  const reasonId = `reason-${p.id}`
                  return (
                    <TableRow key={p.id}>
                      <TableCell>
                        <span style={{ display: "flex", alignItems: "center", gap: "var(--atlas-spacing-3)" }}>
                          <Avatar size="md" initials={initials(p.name)} alt="" />
                          <span style={{ display: "grid" }}>
                            <span>{p.name}{p.you ? " (You)" : ""}</span>
                            <span style={muted}>{p.email}</span>
                          </span>
                        </span>
                      </TableCell>
                      <TableCell>
                        {p.status === "Pending" ? (
                          <span>Invited as {p.role}</span>
                        ) : (
                          <>
                            <Select value={p.role} disabled={protectedOwner} onValueChange={(v) => changeRole(p, v as Role)}>
                              <SelectTrigger size="md" aria-label={`Role for ${p.name}`} aria-describedby={protectedOwner ? reasonId : undefined}>
                                <SelectValue />
                              </SelectTrigger>
                              <SelectContent>
                                {ROLES.map((r) => <SelectItem key={r} value={r}>{r}</SelectItem>)}
                              </SelectContent>
                            </Select>
                            {protectedOwner && <span id={reasonId} style={hidden}>Only Owner. Make another member an Owner first.</span>}
                          </>
                        )}
                      </TableCell>
                      <TableCell><Badge variant={p.status === "Active" ? "success" : "warning"} size="md">{p.status}</Badge></TableCell>
                      <TableCell align="end">
                        <DropdownMenu>
                          <DropdownMenuTrigger asChild>
                            <Button variant="ghost" iconOnly aria-label={`Actions for ${p.name}`}><MoreHorizontal aria-hidden /></Button>
                          </DropdownMenuTrigger>
                          <DropdownMenuContent>
                            {p.status === "Pending" ? (
                              <>
                                <DropdownMenuItem>Resend invite</DropdownMenuItem>
                                <DropdownMenuItem destructive>Revoke invite</DropdownMenuItem>
                              </>
                            ) : p.you ? (
                              <DropdownMenuItem destructive disabled={protectedOwner}>Leave workspace</DropdownMenuItem>
                            ) : (
                              <DropdownMenuItem destructive disabled={protectedOwner} onSelect={() => setRemoving(p)}>
                                Remove from workspace
                              </DropdownMenuItem>
                            )}
                          </DropdownMenuContent>
                        </DropdownMenu>
                      </TableCell>
                    </TableRow>
                  )
                })}
              </TableBody>
            </Table>
          </CardContent>
        </Card>
      )}

      <Dialog open={inviting} onOpenChange={setInviting}>
        <DialogContent size="md">
          <DialogHeader><DialogTitle>Invite member</DialogTitle></DialogHeader>
          <DialogBody>
            <DialogDescription>
              They will get an email with a link to join. Owners can manage billing; Admins can manage members; Members can edit content.
            </DialogDescription>
            {failure && <Alert variant="danger" description={failure} />}
            <Field label="Email address" required>
              {(control) => <Input {...control} type="email" value={email} placeholder="name@company.com" autoComplete="off"
                onChange={(e) => setEmail(e.target.value)} />}
            </Field>
            <Field label="Role">
              {(control) => (
                <Select value={inviteRole} onValueChange={(v) => setInviteRole(v as Role)}>
                  <SelectTrigger {...control} size="md"><SelectValue /></SelectTrigger>
                  <SelectContent>
                    {ROLES.map((r) => <SelectItem key={r} value={r}>{r}</SelectItem>)}
                  </SelectContent>
                </Select>
              )}
            </Field>
          </DialogBody>
          <DialogFooter>
            <DialogClose><Button variant="ghost">Cancel</Button></DialogClose>
            <Button variant="primary" loading={sending} disabled={!email.trim()} onClick={send}>Send invite</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <AlertDialog open={removing !== null} onOpenChange={(o) => { if (!o && !removeBusy) setRemoving(null) }}>
        <AlertDialogContent variant="destructive" state={removeBusy ? "loading" : "default"}>
          <AlertDialogTitle>Remove {removing?.name}?</AlertDialogTitle>
          <AlertDialogDescription>
            {removing?.name.split(" ")[0]} loses access to this workspace and its projects immediately. Their work stays. You can invite them again later.
          </AlertDialogDescription>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={confirmRemove}>Remove {removing?.name.split(" ")[0]}</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  )
}

