                              </SelectTrigger>
                              <SelectContent>
                                {ROLES.map((r) => <SelectItem key={r} value={r}>{r}</SelectItem>)}
                              </SelectContent>
                            </Select>
                            {protectedOwner && <span id={reasonId} style={hidden}>Only Owner. Make another member an Owner first.</span>}
                          </>
                        )}
                      </TableCell>
                      <TableCell><Badge variant={p.status === "Active" ? "success" : "warning"} size="md">{p.status}</Badge></TableCell>
                      <TableCell align="end">
                        <DropdownMenu>
                          <DropdownMenuTrigger asChild>
                            <Button variant="ghost" iconOnly aria-label={`Actions for ${p.name}`}><MoreHorizontal aria-hidden /></Button>
                          </DropdownMenuTrigger>
                          <DropdownMenuContent>
                            {p.status === "Pending" ? (
                              <>
                                <DropdownMenuItem>Resend invite</DropdownMenuItem>
                                <DropdownMenuItem destructive>Revoke invite</DropdownMenuItem>
                              </>
                            ) : p.you ? (
                              <DropdownMenuItem destructive disabled={protectedOwner}>Leave workspace</DropdownMenuItem>
                            ) : (
                              <DropdownMenuItem destructive disabled={protectedOwner} onSelect={() => setRemoving(p)}>
                                Remove from workspace
                              </DropdownMenuItem>
                            )}
                          </DropdownMenuContent>
                        </DropdownMenu>
                      </TableCell>
                    </TableRow>
                  )
                })}
              </TableBody>
            </Table>
          </CardContent>
        </Card>
      )}

      <Dialog open={inviting} onOpenChange={setInviting}>
        <DialogContent size="md">
          <DialogHeader><DialogTitle>Invite member</DialogTitle></DialogHeader>
          <DialogBody>
            <DialogDescription>
              They will get an email with a link to join. Owners can manage billing; Admins can manage members; Members can edit content.
            </DialogDescription>
            {failure && <Alert variant="danger" description={failure} />}
            <Field label="Email address" required>
              {(control) => <Input {...control} type="email" value={email} placeholder="name@company.com" autoComplete="off"
                onChange={(e) => setEmail(e.target.value)} />}
            </Field>
            <Field label="Role">
              {(control) => (
                <Select value={inviteRole} onValueChange={(v) => setInviteRole(v as Role)}>
                  <SelectTrigger {...control} size="md"><SelectValue /></SelectTrigger>
                  <SelectContent>
                    {ROLES.map((r) => <SelectItem key={r} value={r}>{r}</SelectItem>)}
                  </SelectContent>
                </Select>
              )}
            </Field>
          </DialogBody>
          <DialogFooter>
            <DialogClose><Button variant="ghost">Cancel</Button></DialogClose>
            <Button variant="primary" loading={sending} disabled={!email.trim()} onClick={send}>Send invite</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <AlertDialog open={removing !== null} onOpenChange={(o) => { if (!o && !removeBusy) setRemoving(null) }}>
        <AlertDialogContent variant="destructive" state={removeBusy ? "loading" : "default"}>
          <AlertDialogTitle>Remove {removing?.name}?</AlertDialogTitle>
          <AlertDialogDescription>
            {removing?.name.split(" ")[0]} loses access to this workspace and its projects immediately. Their work stays. You can invite them again later.
          </AlertDialogDescription>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={confirmRemove}>Remove {removing?.name.split(" ")[0]}</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  )
}
